import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized tanh kernel operating on float4 chunks via CUTE tensors,
// plus a scalar tail kernel for the remainder elements.

__device__ __forceinline__ float fast_tanhf(float x) {
  // Fast, numerically-safe tanh using __expf intrinsic.
  float e = __expf(-2.0f * fabsf(x));
  float t = (1.0f - e) / (1.0f + e);
  return copysignf(t, x);
}
__global__ __launch_bounds__(256) void tanh_kernel_vec4(const float4* __restrict__ X,
                                  float4* __restrict__ Y,
                                  int64_t N4)
{
  // Vectorized (float4) loads with additional thread-level unrolling (4 vectors
  // per iteration) to increase memory-level parallelism (more outstanding
  // loads in flight) and better saturate DRAM bandwidth, since this kernel
  // is heavily memory-bound (compute throughput ~7%, memory throughput ~89%).
  constexpr int UNROLL = 4;
  int64_t tid    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  int64_t base = tid;
  for (; base + (int64_t)(UNROLL - 1) * stride < N4; base += (int64_t)UNROLL * stride) {
    #pragma unroll
    for (int k = 0; k < UNROLL; ++k) {
      float4 v = __ldcs(&X[base + (int64_t)k * stride]);
      float4 r;
      r.x = fast_tanhf(v.x);
      r.y = fast_tanhf(v.y);
      r.z = fast_tanhf(v.z);
      r.w = fast_tanhf(v.w);
      __stcs(&Y[base + (int64_t)k * stride], r);
    }
  }
  // Tail elements (not enough remaining stride-steps for a full unrolled pass).
  for (int64_t i = base; i < N4; i += stride) {
    float4 v = __ldcs(&X[i]);
    float4 r;
    r.x = fast_tanhf(v.x);
    r.y = fast_tanhf(v.y);
    r.z = fast_tanhf(v.z);
    r.w = fast_tanhf(v.w);
    __stcs(&Y[i], r);
  }
}
__global__ void tanh_kernel_scalar_tail(const float* __restrict__ X,
                                         float* __restrict__ Y,
                                         int64_t start,
                                         int64_t N)
{
  Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N), make_stride(Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N), make_stride(Int<1>{}));
  int64_t idx    = start + (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t i = idx; i < N; i += stride) {
    mY(i) = fast_tanhf(mX(i));
  }
}
torch::Tensor cute_tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  auto y   = torch::empty_like(x_c);

  int64_t N  = x_c.numel();
  int64_t N4 = N / 4;             // number of full float4 groups
  int64_t rem_start = N4 * 4;     // remaining scalar elements start here
  int64_t rem = N - rem_start;

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  int dev = x_c.get_device();
  cudaDeviceProp prop;
  cudaGetDeviceProperties(&prop, dev);
  int sm_count = prop.multiProcessorCount;

  constexpr int Threads = 256;

  if (N4 > 0) {
    int64_t blocks64 = (N4 + Threads - 1) / Threads;
    int blocks = (int)std::min<int64_t>(blocks64, (int64_t)sm_count * 32); // cap grid so grid-stride loop keeps SMs persistently full-occupancy, avoiding tail-wave underutilization
    if (blocks < 1) blocks = 1;

    const float4* x4_ptr = reinterpret_cast<const float4*>(x_ptr);
    float4* y4_ptr = reinterpret_cast<float4*>(y_ptr);

    tanh_kernel_vec4<<<blocks, Threads, 0, stream>>>(x4_ptr, y4_ptr, N4);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "tanh_kernel_vec4 launch failed: ", cudaGetErrorString(err));
  }

  if (rem > 0) {
    int64_t blocks64 = (rem + Threads - 1) / Threads;
    int blocks = (int)std::min<int64_t>(blocks64, (int64_t)sm_count * 32); // cap grid so grid-stride loop keeps SMs persistently full-occupancy, avoiding tail-wave underutilization
    if (blocks < 1) blocks = 1;

    tanh_kernel_scalar_tail<<<blocks, Threads, 0, stream>>>(x_ptr, y_ptr, rem_start, N);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "tanh_kernel_scalar_tail launch failed: ", cudaGetErrorString(err));
  }

  return y;
}
"""

cute_tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh_forward(x)

